using System.ComponentModel.Composition;

[ExportMetadataAttribute(identifierStr(TableName), tableStr(EcoResDateTimeValue))]
[ExportMetadataAttribute(identifierStr(EntityName), dataentityviewstr(CustomerAttributeValueEntity))]
[ExportAttribute(identifierstr(Dynamics.AX.Application.IBusinessEventsTableToEntityRecordIdSelector))]
internal final class CustomerAttributeValueEntityRecordIdSelectorEcoResDateTimeValue implements IBusinessEventsTableToEntityRecordIdSelector
{
}

Method.Source:
[Hookable(false)]
public List getEntityRecordIdsImpactedByTableChange(BusinessEventsDefinition _eventDefinition, BusinessEventsActions _changeType, RecId _changedRecordId)
{
    List impactedRecIds = new List(Types::Int64);
    CustomerInstanceValue customerInstanceValue;
    EcoResAttributeValue ecoResAttributeValue;

    while select RecId from customerInstanceValue
        exists join ecoResAttributeValue
            where ecoResAttributeValue.Value == _changedRecordId
                && ecoResAttributeValue.InstanceValue == customerInstanceValue.RecId
    {
        impactedRecIds.addEnd(customerInstanceValue.RecId);
    }

    return impactedRecIds;
}
